WITH valid AS (SELECT *, shipping_fee - amount AS amount_with_shipping, shipping_fee * discount AS shipping_fee_times_discount, COALESCE(channel, 'UNKNOWN') AS resolved_channel FROM orders WHERE order_date >= DATE '2023-07-20' AND channel IS DISTINCT FROM 'mobile') SELECT s.* FROM valid s WHERE EXISTS (SELECT 1 FROM payments x WHERE x.order_id = s.id AND x.paid_at >= s.order_date);
